<section class="verify-document"><div class="verify-box"><div class="verify-brand"><?php if(!empty($brand['logo'])): ?><img src="<?= htmlspecialchars($brand['logo']) ?>" alt="Logo"><?php else: ?><span>IF</span><?php endif ?><strong><?= htmlspecialchars($brand['name']) ?></strong></div><?php if($certificate): ?><div class="verify-status valid">✓</div><p class="site-kicker">DOCUMENT AUTHENTIQUE</p><h1>Certificat vérifié</h1><p>Ce document a bien été délivré par <?= htmlspecialchars($brand['name']) ?>.</p><dl><div><dt>Bénéficiaire</dt><dd><?= htmlspecialchars($certificate['user_name']) ?></dd></div><div><dt>Formation</dt><dd><?= htmlspecialchars($certificate['course_title']) ?></dd></div><div><dt>Date</dt><dd><?= date('d/m/Y',strtotime($certificate['issued_at'])) ?></dd></div><div><dt>Score</dt><dd><?= (int)$certificate['final_score'] ?>%</dd></div><div><dt>Code</dt><dd><?= htmlspecialchars($certificate['verification_code']?:$certificate['reference']) ?></dd></div></dl><?php else: ?><div class="verify-status invalid">!</div><h1>Document introuvable</h1><p>Aucun document ne correspond au code « <?= htmlspecialchars($code) ?> ».</p><?php endif ?><a class="site-btn green" href="/">Retour à IFMAP</a></div></section><style>.verify-document{min-height:70vh;display:grid;place-items:center;padding:50px 20px}.verify-box{width:min(100%,650px);background:#fff;border:1px solid #dce4df;border-radius:20px;padding:40px;text-align:center;box-shadow:0 20px 55px #173f3915}.verify-brand{display:flex;justify-content:center;align-items:center;gap:10px}.verify-brand img{max-width:90px;max-height:55px}.verify-brand span{width:42px;height:42px;border-radius:12px;display:grid;place-items:center;background:var(--site-primary);color:#fff}.verify-status{width:70px;height:70px;border-radius:50%;display:grid;place-items:center;margin:30px auto 15px;font-size:30px}.verify-status.valid{background:#e3f6ed;color:#168257}.verify-status.invalid{background:#fde9e5;color:#b74939}.verify-box dl{text-align:left;border:1px solid #e5eae7;border-radius:12px;margin:25px 0}.verify-box dl div{display:grid;grid-template-columns:130px 1fr;padding:12px;border-bottom:1px solid #e5eae7}.verify-box dl div:last-child{border:0}.verify-box dt{color:#798681}.verify-box dd{font-weight:700;margin:0}</style>
